package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import android.view.*;import java.lang.reflect.*;import org.json.*;
/** Real Home, sleep/wake, nested Back and Activity recreation; no production test bridge. */
public final class LifecyclePlayerTest extends UnifiedPlayerTest {
 void shell(String cmd)throws Exception{try(ParcelFileDescriptor p=getUiAutomation().executeShellCommand(cmd);java.io.InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] data=new byte[1024];while(in.read(data)!=-1){}}}
 boolean requested()throws Exception{Object c=field("compatibility");if(c!=null){Method m=c.getClass().getDeclaredMethod("wantsPlayback");m.setAccessible(true);return (boolean)m.invoke(c);}return field("player")!=null&&(boolean)playerCall("getPlayWhenReady");}
 boolean fullMode()throws Exception{Field f=activity.getClass().getDeclaredField("nativeFull");f.setAccessible(true);return f.getBoolean(activity);}
 void home()throws Exception{shell("input keyevent 3");waitFor(()->(boolean)field("backgroundSuspended")&&!requested());}
 void bringBack()throws Exception{getTargetContext().startActivity(new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));waitFor(()->activity.hasWindowFocus()||(boolean)field("dialogOpen"));}
 void lock()throws Exception{shell("input keyevent 223");waitFor(()->!((PowerManager)activity.getSystemService(Context.POWER_SERVICE)).isInteractive()&&(boolean)field("backgroundSuspended")&&!requested());}
 void unlock()throws Exception{shell("input keyevent 224");shell("wm dismiss-keyguard");bringBack();}
 void back()throws Exception{sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);SystemClock.sleep(250);}
 @Override void check(String name,Task task){int before=failed;super.check(name,task);if(failed>before)throw new AssertionError("Stopped after failed lifecycle case");}
 @Override public void onStart(){try{shell("input keyevent 224");shell("wm dismiss-keyguard");
 activity=startActivitySync(new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field wf=activity.getClass().getDeclaredField("web");wf.setAccessible(true);web=(WebView)wf.get(activity);waitJS("document.querySelector('#boot')?.hidden===true");
 eval("window.__fixturePending=true;localStorage.setItem('tl-tv-ready','true');localStorage.setItem('tl-prefs',JSON.stringify({autoplay:false,muted:false,motion:false}));const r=indexedDB.open('TiviLoom',1);r.onsuccess=()=>{const tx=r.result.transaction('library','readwrite');tx.objectStore('library').put({version:2,activeId:'fixture',playlists:[{id:'fixture',name:'Local fixture',imported:true,channels:[{id:'one',name:'Fixture One',type:'tv',group:'QA',url:"+JSONObject.quote(arguments.getString("url","http://10.0.2.2:18888/demo.mp4"))+"}],programs:[],favorites:[],history:[]}]},'active');tx.oncomplete=()=>{r.result.close();window.__fixtureReady=true}};");
 waitJS("window.__fixtureReady===true");eval("window.__reloadPending=true;location.replace(location.pathname+'?layout=phone')");
 waitJS("!window.__reloadPending && !!document.querySelector('[data-channel=one]')&&document.querySelector('#boot').hidden");eval("document.querySelector('[data-channel=one]').click()");

 check("preview renders before lifecycle tests",()->waitFor(()->host()!=null&&playing()&&renderedPlayback()));Object original=decoder();onMain(()->{Object p=field("player");if(p!=null)Class.forName("androidx.media3.common.Player",true,activity.getClassLoader()).getMethod("setRepeatMode",int.class).invoke(p,1);return true;});
 check("last-channel startup preference can stay enabled",()->{eval("document.querySelector('[data-tv=settings]').click();document.querySelector('[data-tv=setting-library]').click();const e=document.querySelector('.startup-setting input');if(!e.checked)e.click()");waitJS("JSON.parse(localStorage.getItem('tl-prefs')).autoplay===true");back();back();waitJS("!document.querySelector('#modal-root').children.length");tap("previewPause");waitFor(()->playing());});
 boolean restoreOnly="restore".equals(arguments.getString("mode","all"));if(!restoreOnly){
 check("Home and return preserve playing preview and decoder",()->{home();bringBack();waitFor(()->playing());require(!fullMode()&&decoder()==original,"Home resumed into fullscreen/new decoder");});
 check("paused preview remains paused after Home",()->{tap("previewPause");waitFor(()->!playing());home();bringBack();SystemClock.sleep(500);require(onMain(()->!requested())&&!fullMode()&&decoder()==original,"Paused preview restarted");tap("previewPause");waitFor(()->playing());});
 check("sleep and wake restore the playing preview without fullscreen",()->{lock();unlock();waitFor(()->playing());require(!fullMode()&&decoder()==original,"Wake replaced preview");});
 check("Search query and hidden preview survive repeated lock/Home",()->{eval("document.querySelector('[data-tv=nav-search]').click();var q=document.querySelector('#search-input');q.value='Fixture';q.dispatchEvent(new Event('input',{bubbles:true}))");waitFor(()->!requested());lock();unlock();home();bringBack();waitJS("document.querySelector('#search-input')?.value==='Fixture'&&document.querySelector('#player').hidden");require(!fullMode()&&decoder()==original&&onMain(()->!requested()),"Search resumed playback/fullscreen");});
 check("nested settings survive background and Back removes one layer",()->{eval("document.querySelector('[data-tv=settings]').click();document.querySelector('[data-tv=setting-sources]').click()");home();bringBack();waitJS("!!document.querySelector('.playlist-row')");back();waitJS("!!document.querySelector('[data-tv=setting-library]')");require(!fullMode(),"Settings Back opened fullscreen");back();waitJS("!!document.querySelector('#search-input')");});
 check("fullscreen playback survives Home in the same mode",()->{eval("document.querySelector('[data-tv=nav-guide]').click()");waitFor(()->((View)field("root")).getVisibility()==View.VISIBLE);tap("previewPause");waitFor(()->playing());eval("window.dispatchEvent(new Event('TiviLoomNativeExpand'))");waitJS("!document.querySelector('#player').hidden&&innerWidth>innerHeight");home();bringBack();waitFor(()->playing());require(fullMode()&&decoder()==original,"Fullscreen source/mode changed");});
 check("native sheet survives Home and Back only dismisses the sheet",()->{tapLabel("Kanal siyahısı");home();bringBack();waitFor(()->requested()&&(boolean)field("dialogOpen"));back();waitFor(()->!(boolean)field("dialogOpen"));require(fullMode()&&decoder()==original,"Sheet Back left fullscreen");});
 check("paused and locked fullscreen stays paused and locked after wake",()->{tap("playButton");waitFor(()->!playing());tap("lockButton");lock();unlock();SystemClock.sleep(500);require(fullMode()&&(boolean)field("locked")&&onMain(()->!requested()),"Wake changed paused/locked mode");back();waitFor(()->!(boolean)field("locked"));require(fullMode(),"First Back should unlock only");back();waitJS("document.querySelector('#player').hidden");require(!fullMode(),"Second Back did not exit fullscreen");});
 }if(restoreOnly){
 check("Activity recreation restores Search with autoplay disabled for restore",()->{eval("document.querySelector('[data-tv=nav-search]').click();var q=document.querySelector('#search-input');q.value='Restore me';q.dispatchEvent(new Event('input',{bubbles:true}))");waitJS("JSON.parse(localStorage.getItem('tl-phone-navigation')).query==='Restore me'");ActivityMonitor monitor=addMonitor("com.tiviloom.mobile.MainActivity",null,false);runOnMainSync(()->activity.recreate());Activity next=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);require(next!=null&&next!=activity,"Activity was not recreated");activity=next;Field f=activity.getClass().getDeclaredField("web");f.setAccessible(true);web=(WebView)f.get(activity);waitJS("document.querySelector('#boot').hidden&&document.querySelector('#search-input')?.value==='Restore me'");require(!fullMode()&&host()==null,"Recreation autoplayed into fullscreen");});
 }
 }catch(Throwable e){failed++;report.append("FATAL ").append(e.toString());}finally{try{shell("input keyevent 224");shell("wm dismiss-keyguard");}catch(Exception ignored){}if(activity!=null)runOnMainSync(()->activity.finish());}Bundle out=new Bundle();out.putString("stream",report+"\nPASSED="+passed+" FAILED="+failed+"\n");finish(failed==0?-1:0,out);}
}
